'use client';

import { zodResolver } from '@hookform/resolvers/zod';
import { useForm, Controller } from 'react-hook-form';
import { z } from 'zod';
import { Button } from '@/components/ui/button';
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Slider } from '@/components/ui/slider';
import { Switch } from '@/components/ui/switch';
import { Checkbox } from '@/components/ui/checkbox';
import { ROLES } from '@/lib/constants';
import type { Role } from '@/lib/types';
import { createGame } from '@/app/actions';
import { useTransition, useState, useMemo } from 'react';
import { Loader2, Shield, Swords, Sparkles, AlertCircle } from 'lucide-react';

const allRoles = Object.values(ROLES);

const FormSchema = z.object({
  playerCount: z.number().min(5).max(10),
  aiCount: z.number().min(0).max(9),
  roles: z.array(z.string()).refine((value) => value.some((item) => item), {
    message: 'You have to select at least one role.',
  }),
  gameId: z.string().optional(),
  chatEnabled: z.boolean(),
}).refine(data => data.playerCount > data.aiCount, {
    message: "AI count cannot be greater than or equal to player count.",
    path: ["aiCount"],
});

type FairnessResult = {
  isFair: boolean;
  explanation: string;
} | null;

export function CreateGameForm() {
  const [isPending, startTransition] = useTransition();
  const [fairnessResult, setFairnessResult] = useState<FairnessResult>(null);

  const form = useForm<z.infer<typeof FormSchema>>({
    resolver: zodResolver(FormSchema),
    defaultValues: {
      playerCount: 5,
      aiCount: 0,
      roles: ['Merlin', 'Percival', 'Loyal Servant of Arthur', 'Assassin', 'Morgana'],
      gameId: '',
      chatEnabled: true,
    },
  });

  const playerCount = form.watch('playerCount');
  const aiCount = form.watch('aiCount');
  const selectedRoles = form.watch('roles');
  
  const { goodRolesCount, evilRolesCount } = useMemo(() => {
    return selectedRoles.reduce((acc, roleName) => {
      const role = ROLES[roleName as Role['name']];
      if (role) {
        if (role.alignment === 'good') acc.goodRolesCount++;
        else acc.evilRolesCount++;
      }
      return acc;
    }, { goodRolesCount: 0, evilRolesCount: 0 });
  }, [selectedRoles]);
  
  const totalRolesCount = goodRolesCount + evilRolesCount;

  function onSubmit(data: z.infer<typeof FormSchema>) {
    startTransition(async () => {
      const result = await createGame(data);
      if (result?.fairness) {
        setFairnessResult(result.fairness);
      }
    });
  }
  
  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
        <FormField
          control={form.control}
          name="playerCount"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Player Count: {field.value}</FormLabel>
              <FormControl>
                <Controller
                  name="playerCount"
                  control={form.control}
                  render={({ field }) => (
                    <Slider
                      min={5}
                      max={10}
                      step={1}
                      value={[field.value]}
                      onValueChange={(vals) => field.onChange(vals[0])}
                    />
                  )}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="aiCount"
          render={({ field }) => (
            <FormItem>
              <FormLabel>AI Count</FormLabel>
              <FormControl>
                <Input type="number" min="0" max={playerCount - 1} {...field} onChange={e => {
                  const value = e.target.value;
                  if (value === '') {
                    field.onChange(0); // Or handle empty string as you see fit, maybe 0 is best
                  } else {
                    field.onChange(parseInt(value, 10));
                  }
                }} />
              </FormControl>
              <FormDescription>
                {playerCount - aiCount} human players needed.
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />
        
        <FormField
          control={form.control}
          name="roles"
          render={() => (
            <FormItem>
              <div className="mb-4">
                <FormLabel className="text-base">Roles</FormLabel>
                <FormDescription>
                  Select roles for the game. Total must equal player count.
                </FormDescription>
              </div>
              <div className="grid grid-cols-2 gap-4">
                {allRoles.map((role) => (
                  <FormField
                    key={role.name}
                    control={form.control}
                    name="roles"
                    render={({ field }) => (
                      <FormItem
                        key={role.name}
                        className="flex flex-row items-start space-x-3 space-y-0"
                      >
                        <FormControl>
                          <Checkbox
                            checked={field.value?.includes(role.name)}
                            onCheckedChange={(checked) => {
                              return checked
                                ? field.onChange([...field.value, role.name])
                                : field.onChange(
                                    field.value?.filter(
                                      (value) => value !== role.name
                                    )
                                  );
                            }}
                          />
                        </FormControl>
                        <FormLabel className="font-normal flex items-center gap-2">
                           {role.alignment === 'good' ? <Shield className="h-4 w-4 text-blue-400" /> : <Swords className="h-4 w-4 text-red-400" />}
                          {role.name}
                        </FormLabel>
                      </FormItem>
                    )}
                  />
                ))}
              </div>
              <FormMessage />
              <div className={`mt-2 text-sm flex justify-between p-2 rounded-md ${totalRolesCount !== playerCount ? 'text-destructive bg-destructive/20' : 'text-foreground bg-secondary'}`}>
                <span>Total Roles: {totalRolesCount} / {playerCount}</span>
                <div className="flex gap-4">
                  <span className="flex items-center gap-1"><Shield className="h-4 w-4" /> Good: {goodRolesCount}</span>
                  <span className="flex items-center gap-1"><Swords className="h-4 w-4" /> Evil: {evilRolesCount}</span>
                </div>
              </div>
            </FormItem>
          )}
        />
        
        {fairnessResult && (
          <div className={`flex items-start gap-2 p-3 rounded-md border ${fairnessResult.isFair ? 'border-green-500/50 bg-green-500/10 text-green-300' : 'border-destructive/50 bg-destructive/10 text-destructive'}`}>
            {fairnessResult.isFair ? <Sparkles className="h-5 w-5 mt-0.5 text-green-400" /> : <AlertCircle className="h-5 w-5 mt-0.5 text-destructive" />}
            <div>
                <p className="font-bold">{fairnessResult.isFair ? 'Fairness Check Passed' : 'Fairness Check Failed'}</p>
                <p className="text-xs">{fairnessResult.explanation}</p>
            </div>
          </div>
        )}

        <FormField
          control={form.control}
          name="gameId"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Custom Game ID (Optional)</FormLabel>
              <FormControl>
                <Input placeholder="RANDOM6" {...field} onChange={(e) => field.onChange(e.target.value.toUpperCase())} maxLength={6} />
              </FormControl>
              <FormDescription>
                6-character ID (A-Z, 0-9). Leave blank for random.
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />
        
        <FormField
          control={form.control}
          name="chatEnabled"
          render={({ field }) => (
            <FormItem className="flex flex-row items-center justify-between rounded-lg border p-3 shadow-sm">
              <div className="space-y-0.5">
                <FormLabel>Enable Chat</FormLabel>
                <FormDescription>
                  In-game chat for players. Required if AI players are present.
                </FormDescription>
              </div>
              <FormControl>
                <Switch
                  checked={field.value}
                  onCheckedChange={field.onChange}
                  disabled={aiCount > 0}
                />
              </FormControl>
            </FormItem>
          )}
        />
        
        <Button type="submit" className="w-full" disabled={isPending || totalRolesCount !== playerCount}>
          {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
          Create Game
        </Button>
      </form>
    </Form>
  );
}
